/// One-shot `RepoSession::commit`: update the wc commit's
/// description and start a new empty change on top (`jj commit`).
pub fn commit(repo: &Path, desc: &str) -> Result<()> {
    session::RepoSession::open(repo)?.commit(desc)
}

