83	/// True when `revset` references a working copy, so the query must
84	/// snapshot before resolving (an op-store write) to see the
85	/// filesystem as it is right now, like the CLI's auto-snapshot.
86	///
87	/// A `@` is working-copy syntax (`@`, `@-`, `ws@`) unless it has
88	/// symbol characters on *both* sides, which is the remote-bookmark
89	/// form (`name@remote`).
90	fn references_working_copy(revset: &str) -> bool {
91	    let is_symbol_char =
92	        |c: char| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | '/' | '+');
93	    let chars: Vec<char> = revset.chars().collect();
94	    chars.iter().enumerate().any(|(i, &c)| {
95	        c == '@'
96	            && !(i > 0
97	                && is_symbol_char(chars[i - 1])
98	                && chars.get(i + 1).copied().is_some_and(is_symbol_char))
99	    })
100	}
