    if let Some(id) = &new_wc_commit_id {
        let new_wc_commit = self.repo.store().get_commit(id)?;
        let old_tree = old_wc_commit.as_ref().map(|c| c.tree());
        self.workspace
            .check_out(self.repo.op_id().clone(), old_tree.as_ref(), &new_wc_commit)
            .block_on()?;
    }
