1	//! Typed facade over jj: reads and the publish-path mutations, all
2	//! in-process through jj-lib (the jj-lib migration stage of
3	//! `notes/refactor-20260716.md`).
4	//!
5	//! Reads resolve through `common::load_repo` +
6	//! `common::resolve_revset` and `Commit` accessors. A revset that
7	//! references a working copy (`@`, `@-`, `ws@`) snapshots first
8	//! (`repo_for_read`), so "right now" questions answer about the
9	//! filesystem the way the spawned CLI's auto-snapshot did.
10	//! Mutations are `session::RepoSession` methods. The verb fns here
11	//! are one-shot wrappers (open a session, run the verb) for
12	//! context-less callers. Context-ful callers (push, squash-push,
13	//! sync) go through `Context::session`, which caches one open
14	//! session per repo for the whole invocation.
15	//!
16	//! - `matches` / `rev_exists`: does a revset match / does a
17	//!   revision resolve.
18	//! - `chid_of` / `cid_of` / `cid_short_of` / `cids_short_of`:
19	//!   change / commit ids.
20	//! - `desc_of` / `is_empty`: description and emptiness.
21	//! - `local_bookmark_exists` / `non_tracking_remote_of` /
22	//!   `has_tracked_remote`: typed bookmark and remote-ref queries
23	//!   over the view (they replaced parsing `jj bookmark list`
24	//!   output).
25	//! - `diff_stat`: a `diff --stat`-shaped summary of `@` against
26	//!   its parents.
27	//! - `is_no_such_revision`: the typed unresolvable-revision test.
28	//! - `commit` / `describe` / `bookmark_set` / `git_push_bookmark` /
29	//!   `new_on` / `rebase_branch`: one-shot wrappers over the session
30	//!   verbs. `git_fetch` has no wrapper: its only caller (sync) is
31	//!   context-ful.
32	//!
33	//! Still spawning `jj` elsewhere: the call sites outside the
34	//! session verbs (`jj squash`, `jj op log` / `op restore`,
35	//! `jj git clone`, repo-init plumbing).
36	
37	use std::path::Path;
38	
39	use futures::AsyncReadExt as _;
40	use jj_lib::backend::TreeValue;
41	use jj_lib::commit::Commit;
42	use jj_lib::diff::ContentDiff;
43	use jj_lib::diff::DiffHunkKind;
44	use jj_lib::matchers::EverythingMatcher;
45	use jj_lib::merged_tree::TreeDiffIterator;
46	use jj_lib::object_id::ObjectId;
47	use jj_lib::ref_name::RefName;
48	use jj_lib::ref_name::RemoteName;
49	use jj_lib::repo::Repo;
50	use jj_lib::revset::RevsetResolutionError;
51	use pollster::FutureExt;
52	
53	use crate::common;
54	
55	pub(crate) mod session;
56	
57	/// Crate-standard boxed-error result, aliased locally for brevity.
58	type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
59	
60	/// One-shot `RepoSession::commit`: update the wc commit's
61	/// description and start a new empty change on top (`jj commit`).
62	pub fn commit(repo: &Path, desc: &str) -> Result<()> {
63	    session::RepoSession::open(repo)?.commit(desc)
64	}
65	
66	/// One-shot `RepoSession::describe`: rewrite `rev`'s description
67	/// and rebase its descendants (`jj describe -r <rev> -m <desc>`).
68	pub fn describe(repo: &Path, rev: &str, desc: &str) -> Result<()> {
69	    session::RepoSession::open(repo)?.describe(rev, desc)
70	}
71	
72	/// One-shot `RepoSession::bookmark_set`: point local bookmark
73	/// `name` at `rev` (`jj bookmark set <name> -r <rev>`).
74	pub fn bookmark_set(repo: &Path, name: &str, rev: &str) -> Result<()> {
75	    session::RepoSession::open(repo)?.bookmark_set(name, rev)
76	}
77	
78	/// One-shot `RepoSession::git_push_bookmark`: push local bookmark
79	/// `name` to `origin` (`jj git push --bookmark <name>`).
80	pub fn git_push_bookmark(repo: &Path, name: &str) -> Result<()> {
81	    session::RepoSession::open(repo)?.git_push_bookmark(name)
82	}
83	
84	/// One-shot `RepoSession::new_on`: fresh empty `@` on top of `rev`
85	/// (`jj new <rev>`).
86	pub fn new_on(repo: &Path, rev: &str) -> Result<()> {
87	    session::RepoSession::open(repo)?.new_on(rev)
88	}
89	
90	/// One-shot `RepoSession::rebase_branch`: rebase the branch of
91	/// `source` onto `dest` (`jj rebase -b <source> -d <dest>`).
92	pub fn rebase_branch(repo: &Path, source: &str, dest: &str) -> Result<()> {
93	    session::RepoSession::open(repo)?.rebase_branch(source, dest)
94	}
95	
96	/// True when `revset` references a working copy, so the query must
97	/// snapshot before resolving (an op-store write) to see the
98	/// filesystem as it is right now, like the CLI's auto-snapshot.
99	///
100	/// A `@` is working-copy syntax (`@`, `@-`, `ws@`) unless it has
101	/// symbol characters on *both* sides, which is the remote-bookmark
102	/// form (`name@remote`).
103	fn references_working_copy(revset: &str) -> bool {
104	    let is_symbol_char =
105	        |c: char| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | '/' | '+');
106	    let chars: Vec<char> = revset.chars().collect();
107	    chars.iter().enumerate().any(|(i, &c)| {
108	        c == '@'
109	            && !(i > 0
110	                && is_symbol_char(chars[i - 1])
111	                && chars.get(i + 1).copied().is_some_and(is_symbol_char))
112	    })
113	}
114	
115	/// Load `repo` for a read of `revset`: a working-copy-relative
116	/// revset snapshots first so "right now" questions answer about the
117	/// filesystem, and anything else is a plain read-only load.
118	fn repo_for_read(
119	    repo: &Path,
120	    revset: &str,
121	) -> Result<(
122	    jj_lib::workspace::Workspace,
123	    std::sync::Arc<jj_lib::repo::ReadonlyRepo>,
124	)> {
125	    if references_working_copy(revset) {
126	        let mut ses = session::RepoSession::open(repo)?;
127	        ses.snapshot()?;
128	        Ok((ses.workspace, ses.repo))
129	    } else {
130	        common::load_repo(repo)
131	    }
132	}
133	
134	/// Resolve `revset` in-process and return its commits, in revset
135	/// order (newest first, matching `jj log`).
136	fn commits_of(repo: &Path, revset: &str) -> Result<Vec<Commit>> {
137	    let (workspace, repo_at_head) = repo_for_read(repo, revset)?;
138	    let ids = common::resolve_revset(&workspace, &repo_at_head, revset)?;
139	    ids.iter()
140	        .map(|id| Ok(repo_at_head.store().get_commit(id)?))
141	        .collect()
142	}
143	
144	/// True when `revset` matches at least one commit in `repo`.
145	///
146	/// A valid-but-empty revset (e.g. `conflicts()` on a clean repo)
147	/// is `Ok(false)`; an unresolvable revision is an `Err`, which
148	/// `rev_exists` folds to `false`.
149	pub fn matches(repo: &Path, revset: &str) -> Result<bool> {
150	    let (workspace, repo_at_head) = repo_for_read(repo, revset)?;
151	    Ok(!common::resolve_revset(&workspace, &repo_at_head, revset)?.is_empty())
152	}
153	
154	/// True when `rev` resolves in `repo`.
155	///
156	/// Folds jj's unresolvable-revision error (`is_no_such_revision`,
157	/// either path) to `Ok(false)`. Other failures (bad repo path,
158	/// spawn error) stay `Err`.
159	pub fn rev_exists(repo: &Path, rev: &str) -> Result<bool> {
160	    match matches(repo, rev) {
161	        Ok(found) => Ok(found),
162	        Err(e) if is_no_such_revision(e.as_ref()) => Ok(false),
163	        Err(e) => Err(e),
164	    }
165	}
166	
167	/// True when `e` is jj's unresolvable-revision error, the typed
168	/// `RevsetResolutionError::NoSuchRevision` (every rev query is
169	/// in-process now, so the stderr-wording fallback is gone).
170	pub fn is_no_such_revision(e: &(dyn std::error::Error + 'static)) -> bool {
171	    matches!(
172	        e.downcast_ref::<RevsetResolutionError>(),
173	        Some(RevsetResolutionError::NoSuchRevision { .. })
174	    )
175	}
176	
177	/// The 12-character change id of `rev`.
178	pub fn chid_of(repo: &Path, rev: &str) -> Result<String> {
179	    Ok(commits_of(repo, rev)?
180	        .iter()
181	        .map(common::format_chid)
182	        .collect())
183	}
184	
185	/// The full commit id of `rev`.
186	pub fn cid_of(repo: &Path, rev: &str) -> Result<String> {
187	    Ok(commits_of(repo, rev)?
188	        .iter()
189	        .map(|c| c.id().hex())
190	        .collect())
191	}
192	
193	/// The 12-character commit id of `rev`.
194	pub fn cid_short_of(repo: &Path, rev: &str) -> Result<String> {
195	    Ok(cids_short_of(repo, rev)?.concat())
196	}
